func auditSectionContentDataLinks(sections []SectionData, index datahelpers.PageURLIndex, indexOK bool) []contentDataLinkFinding {
	if !indexOK || len(index) == 0 { return nil }
	var out []contentDataLinkFinding
	for i := range sections {
		if datahelpers.HasRuntimeFillMarker(sections[i].HTML) { continue }  // lockstep with the markup pass
		for _, f := range datahelpers.RepairContentDataLinks(sections[i].ContentData, index) {
			out = append(out, contentDataLinkFinding{Component: sections[i].ComponentName, Path: f.Path, Href: f.Href, NewHref: f.NewHref, Action: f.Action})
		}
	}
	return out
